sys_script_fix.script:
(function() {

    if (!GlidePluginManager.isUpgradeSystemBusy()) {
        return;
    }
    var sysDictionaryGr = new GlideRecord("sys_dictionary");
    sysDictionaryGr.addQuery("name", "sn_install_base_sold_product");
    sysDictionaryGr.addQuery("element", "consumer");
    sysDictionaryGr.query();
    if (!sysDictionaryGr.next()) {
        return;
    }
    sysDictionaryGr.setValue("reference_qual", "javascript:new sn_install_base.SoldProductAndInstallBaseFilter().getConsumerRefQulifier(current)");
    sysDictionaryGr.update();


})();
